if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warrior.dps.Name"] = "Урон в ближнем бою"
L["rm.era.warrior.dps.Description"] = "Уровни 1–60, «Оружие» и «Неистовство», а также любой воин вне Оборонительной стойки, в том числе в игровых мирах «Хардкор» и Self-Found; составлено по симулятор, Icy Veins и Wowhead. Рывок для начала боя, Перехват по далёкой цели, Вихрь (до его изучения — Удар грома) против трёх и более врагов, сражающихся с вами, затем в первую очередь Казнь ниже 20%, Раскол брони до пяти на боссах без Ослабления доспеха, Кровожадность, Смертельный удар, Сокрушение сразу после удара оружием при Улучшенном сокрушении (настроено для двуручного оружия; измените это в копии), Вихрь с сохранением ярости для основного удара, Превосходство, Кровопускание, пока основной удар не изучен, Раскол брони по целям с большим запасом здоровья и Подрезать сухожилия у предела ярости. Напоминания: Боевой крик, Удар героя от 40 ярости (20 при прокачке), Рассекающий удар против групп, Кровавая ярость, Размашистые удары, Инстинкт смерти (на боссах — в последние 30 секунд), Безрассудство вместе с Инстинктом смерти, Зуботычина или Удар щитом. Устрашающий крик и Возмездие есть в списке, но выключены — для экстренных случаев в режиме «Хардкор»; смена стоек остаётся за вами."
L["rm.era.warrior.protection.Name"] = "Танк"
L["rm.era.warrior.protection.Description"] = "Выбирается всякий раз, когда вы в Оборонительной стойке («Защита», «Неистовство» с защитой или танк с двуручным оружием); составлено по Icy Veins и MaxDps. Против четырёх и более врагов: Деморализующий крик и Боевой крик для угрозы. Затем Реванш, Сокрушение щитом, Кровожадность, Раскол брони до пяти, Деморализующий крик против элитных противников, Раскол брони как заполнитель и Кровопускание перед Сокрушением щитом или Кровожадностью. Сокрушение щитом и Блок щитом — только с надетым щитом. Напоминания: Боевой крик, Блок щитом, пока цель бьёт вас, Кровавая ярость, Удар героя и Рассекающий удар от 50 ярости, Удар щитом, Ни шагу назад. Провокация, Глухая оборона и Инстинкт смерти есть в списке, но выключены; Боевая стойка ради Казни (тогда вступает встроенная ротация урона) и Вызывающий крик остаются за вами."
L["rm.era.warrior.protection.icyveins.Name"] = "Танк, угроза Боевым криком (Icy Veins)"
L["rm.era.warrior.protection.icyveins.Description"] = "Танкование «без Раскола брони» по Icy Veins для групп, где ваш крик слышат четыре и более игрока (Боевой крик с 5-й фазы), — альтернатива рекомендуемой встроенной ротации танка, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Деморализующий крик постоянно поддерживается, Реванш, Сокрушение щитом или Кровожадность, затем Боевой крик как заполнитель для угрозы вместо Раскола брони; Сокрушение щитом и Блок щитом — только с надетым щитом. Те же напоминания, что и в рекомендуемой ротации танка; возвращайтесь к Расколу брони, когда сосредоточены на одной цели в толпе."
L["rm.forever.warrior.dps.Name"] = "Оружие и Неистовство (Icy Veins)"
L["rm.forever.warrior.dps.Description"] = "Оружие и Неистовство в ближнем бою с 1 по 60 уровень; также используется по умолчанию для любого воина вне Оборонительной стойки. В Forever ярости мало, и она скрыта от аддонов, поэтому ротация копит её: на всё остальное ярость тратится, только пока восстанавливаются Смертельный удар или Кровожадность: Рывок для начала боя, Победный раж, Перехват, Казнь (в её диапазоне) на элитных противниках, боссах или в группе, Вихрь или Удар грома, Деморализующий крик и Сокрушение против групп врагов, Пробивающий удар против великанов и драконов, Кровопускание до изучения Кровожадности, Превосходство, Смертельный удар, Кровожадность, затем Вихрь, Сокрушение, пока вы стоите на месте, и два Раскола брони (пять на элитных противниках). Напоминания: Боевой крик, Кровавая ярость, прерывание, Удар героя, пока восстанавливается основной удар, Рассекающий удар против групп, Размашистые удары, Инстинкт смерти и Ярость берсерка; Безрассудство и Возмездие есть в списке, но выключены. За вами остаются: смена стоек, Подрезать сухожилия и расходуемые предметы."
L["rm.forever.warrior.dps.warcrafttavern.Name"] = "Оружие и Неистовство, трата ярости (Warcraft Tavern)"
L["rm.forever.warrior.dps.warcrafttavern.Description"] = "Список Warcraft Tavern «всегда тратить» для групп и рейдов: сначала пять Расколов брони, Казнь выше всего остального при здоровье цели ниже 20%, Превосходство, Кровопускание до изучения Кровожадности, Смертельный удар, Кровожадность, Вихрь, Пробивающий удар по готовности, Сокрушение, как только взято Улучшенное сокрушение; Удар героя или Рассекающий удар всякий раз, когда хватает ярости (в Forever ярость скрыта, поэтому порога в 60 ярости и Подрезать сухожилия при лишней ярости нет), Безрассудство по готовности вместе с Инстинктом смерти. Выбирайте её вместо встроенной ротации Icy Veins, если играете в группах и вам не нужно копить ярость между боями. Альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.forever.warrior.protection.Name"] = "Защита (Icy Veins)"
L["rm.forever.warrior.protection.Description"] = "Танкование всегда, когда вы в Оборонительной стойке, с 10 по 60 уровень. Начинает бой Рывком (в Оборонительной стойке, как только у вас есть Авангард), Победный раж, а при двух и более врагах — Удар грома по готовности, Деморализующий крик, Сокрушение щитом, Реванш и Кровопускание. Против одной цели: Сокрушение щитом, Реванш, Деморализующий крик, Кровопускание, Раскол брони (пять на элитных противниках) и Удар грома по опасным целям. Напоминания: Боевой крик, Кровавая ярость, Удар щитом, Блок щитом, пока цель держится на вас, Удар героя, пока Сокрушение щитом и Реванш оба восстанавливаются, Рассекающий удар против групп; Провокация и Глухая оборона есть в списке, но выключены. В Forever ярость, здоровье и мана цели скрыты от аддонов, поэтому пороги ярости, заклинатели и «Ни шагу назад» остаются за вами. За вами остаются: переход в Боевую стойку для Рывка до получения Авангарда, провокация других врагов и подхват отбившихся."
L["rm.forever.warrior.protection.warcrafttavern.Name"] = "Защита, поддержание отрицательных эффектов (Warcraft Tavern)"
L["rm.forever.warrior.protection.warcrafttavern.Description"] = "Порядок танкования от Warcraft Tavern: сначала на каждой цели поддерживаются Удар грома, Деморализующий крик и пять Расколов брони, затем Реванш, Кровопускание и последним — Сокрушение щитом, а Удар героя или Рассекающий удар — всякий раз, когда хватает ярости (в Forever ярость скрыта, поэтому порога в 60 ярости нет). Без Блока щитом и напоминаний о защитных способностях. Выбирайте её вместо встроенной ротации танка Icy Veins, если предпочитаете сначала поддерживать отрицательные эффекты. Альтернатива рекомендуемой встроенной ротации «Защита», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.mop.warrior.arms.Name"] = "Рекомендуемая"
L["rm.mop.warrior.arms.Description"] = "Рекомендуется для «Оружия» с 10 по 90 уровень; выбирается в специализации «Оружие». Рывок для начала боя и снова ради ярости, когда вы отходите. Удар колосса всякий раз, когда его нет или он вот-вот закончится, Смертельный удар, Удар громовержца в окне Удара колосса, Рев дракона и Вихрь клинков вне него. При здоровье цели ниже 20%: Казнь в окне, при 100 ярости или для поддержания Внезапной казни, Превосходство при Вкусе крови. Иначе Мощный удар в окне, Превосходство при четырёх наложениях, Мощный удар при 100 ярости, Превосходство, Мощный удар. Когда с вами сражаются два и более врага, добавляются Размашистые удары, Удар грома ради Глубоких ран, Вихрь клинков и Рев дракона. Победный раж при здоровье ниже 70%; Боевой крик ради ярости. Напоминания: крик, если ни один не действует, Боевая стойка, Ярость берсерка, Безрассудство, Аватара и Кровавая баня вместе с Ударом колосса в долгих боях, Знамя с черепом, Удар героя или Рассекающий удар при лишней ярости, Героический прыжок в окне, Зуботычина, Бой насмерть и Безудержное восстановление при низком здоровье. Сокрушительный бросок есть в списке, но выключен. За вами остаются: отмена Вихря клинков, смена стоек и позиционирование."
L["rm.mop.warrior.arms.icyveins.Name"] = "Накопление к Удару колосса (Icy Veins)"
L["rm.mop.warrior.arms.icyveins.Description"] = "По умолчанию выключена. Порядок «Оружия» по Icy Veins и Wowhead: вне окна Удара колосса использует Превосходство, а Мощный удар — только при ярости выше 80, копя ярость к окну, а не используя Мощный удар как заполнитель. В окне: Смертельный удар, Мощный удар, Превосходство, Героический бросок. При здоровье цели ниже 20%: Удар колосса, Смертельный удар, Казнь, Превосходство, Рев дракона. Размашистые удары против двух врагов, список с Ударом грома против групп из трёх и более. Удар героя или Рассекающий удар — только у предела ярости. Те же напоминания, что и в рекомендуемой встроенной ротации «Оружие». Чтобы использовать её, включите её и выключите ту."
L["rm.mop.warrior.fury.Name"] = "Рекомендуемая"
L["rm.mop.warrior.fury.Description"] = "Рекомендуется для «Неистовства» с 10 по 90 уровень; выбирается в специализации «Неистовство». Рывок для начала боя и ради ярости. Удар колосса, как только накоплены два заряда Яростного выпада (один при Безрассудстве), Яростный выпад перед закрытием окна, Кровожадность, Удар колосса, Удар громовержца, Рев дракона вне окна, здесь Казнь при Единстве намерений (одноручное оружие), Вихрь клинков, пока Кровожадность восстанавливается, при Хватке титана (двуручное оружие) ещё один Яростный выпад вне окна, Казнь, Зверский удар при Приливе крови, Яростный выпад с сохранением заряда для следующего окна, Зверский удар, Героический бросок, Боевой крик ради ярости. Когда с вами сражаются два и более врага, добавляются Вихрь клинков, Рев дракона, Вихрь ради Кровавого фарша и Яростные выпады по нескольким целям. Напоминания: крик, если ни один не действует, Боевая стойка, Ярость берсерка ради Исступления, Безрассудство, Аватара и Кровавая баня вместе с Ударом колосса в долгих боях, Знамя с черепом, Удар героя или Рассекающий удар при лишней ярости, Героический прыжок, Зуботычина и защитные способности при низком здоровье. За вами остаётся: отмена Вихря клинков."
L["rm.mop.warrior.fury.icyveins.Name"] = "Способности с восстановлением в окне Удара колосса (Icy Veins)"
L["rm.mop.warrior.fury.icyveins.Description"] = "По умолчанию выключена. Порядок «Неистовства» по Icy Veins тратит Вихрь клинков или Рев дракона в первую очередь в окне Удара колосса и ставит Казнь перед Кровожадностью при здоровье цели ниже 20%. Вне окна: Удар колосса, Кровожадность, Яростный выпад только при двух зарядах, Зверский удар при Приливе крови, крик, Зверский удар. Четыре и более врага: Кровожадность ради Исступления, Вихрь до трёх наложений Кровавого фарша, Яростный выпад. Удар героя или Рассекающий удар — только у предела ярости. Те же напоминания, что и в рекомендуемой встроенной ротации «Неистовство». Чтобы использовать её, включите её и выключите ту."
L["rm.mop.warrior.protection.Name"] = "Рекомендуемая"
L["rm.mop.warrior.protection.Description"] = "Танкование с 10 по 90 уровень; выбирается при специализации «Защита». Рывок или Героический бросок для начала боя. Сокрушение для поддержания трёх наложений Ослабленной брони на элитных противниках и боссах, Рев дракона, Вихрь клинков, Ударная волна против трёх врагов и Удар грома по готовности против трёх и более. Затем Реванш на последнюю ярость Блока щитом, Мощный удар щитом, Реванш при Дисциплине защитника, Сокрушение ради Глубоких ран, Победный раж при здоровье ниже 60%, Реванш, Удар грома ради Слабых ударов, Казнь, Удар громовержца, крик ради ярости и Сокрушение (до 26 уровня — Раскол брони). Напоминания: Оборонительная стойка, крик, если ни один не действует, Блок щитом всякий раз, когда его нет, Непроницаемый щит при ранении и лишней ярости, Удар героя или Рассекающий удар при Ультиматуме, Побуждении или у предела ярости, Деморализующий крик, Ярость берсерка, Безудержное восстановление, Ни шагу назад и Глухая оборона при низком здоровье, ваши атакующие способности с восстановлением, Зуботычина. Провокация и Героический прыжок есть в списке, но выключены. За вами остаются: кого провоцировать и выбор между Блоком и Непроницаемым щитом против магии."
L["rm.mop.warrior.unspecialized.Name"] = "Без специализации"
L["rm.mop.warrior.unspecialized.Description"] = "Для уровней 1–9 или до выбора специализации. Рывок для начала боя, Победный раж, Казнь и Удар героя при 30 ярости; напоминает встать в Боевую стойку, если вы не в стойке."
L["rm.retail.warrior.arms.Name"] = "Боевой помощник Blizzard"
L["rm.retail.warrior.arms.Description"] = "Рекомендуется для специализации «Оружие» в Midnight. В бою игра теперь скрывает от аддонов ярость, Кровопускание, Удар колосса, срабатывания, время восстановления и здоровье, поэтому эта ротация показывает собственное предложение Боевого помощника Blizzard (ротация одной кнопкой) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: Удар героя (основная кнопка, которую предложение никогда не использует), Аватара и Копье защитника в бою, Боевой крик между боями, Зуботычина против прерываемого заклинания (она загорается только там, где игра позволяет прочитать заклинание), Бой насмерть по готовности в бою (здоровье на Retail скрыто, поэтому момент его применения — на ваше усмотрение)."
L["rm.retail.warrior.arms.colossus.Name"] = "Колосс, для справки (SimulationCraft)"
L["rm.retail.warrior.arms.colossus.Description"] = "Только для справки, по умолчанию выключена: порядок Колосса от SimulationCraft и Icy Veins накапливает Колоссальную мощь Смертельным ударом и читает положительные эффекты, которые Midnight скрывает в бою. Начало боя: Рывок; Размашистые удары против двух и более; Смертельный удар при менее чем пяти наложениях Колоссальной мощи; Кровопускание перед Ударом колосса; Опустошитель; Казнь при двух зарядах Внезапной смерти; Удар колосса; Копье защитника; Разрушение во время Удара колосса с Колоссальной мощью; Удар героя; Смертельный удар; Казнь; Превосходство; Кровопускание, если осталось меньше 5 секунд; Вихрь клинков против двух и более; Мощный удар. Напоминания: Аватара, Бой насмерть, Боевой крик, Зуботычина."
L["rm.retail.warrior.arms.slayer.Name"] = "Истребитель, для справки (SimulationCraft)"
L["rm.retail.warrior.arms.slayer.Description"] = "Только для справки, по умолчанию выключена: порядок Истребителя от SimulationCraft, Icy Veins и Wowhead читает ярость, Кровопускание, Удар колосса, Внезапную смерть и Оппортунизм, которые Midnight скрывает в бою. Начало боя: Рывок; Размашистые удары против двух и более врагов, вступивших в бой; Кровопускание перед Ударом колосса, когда оно заканчивается; Опустошитель прямо перед Ударом колосса; Казнь при двух зарядах Внезапной смерти; Удар колосса; Вихрь клинков во время Удара колосса или Аватары; Удар героя; Превосходство при двух зарядах Оппортунизма; Смертельный удар; Казнь; Превосходство; Кровопускание, если осталось меньше 5 секунд; Мощный удар. Напоминания: Аватара при готовом Ударе колосса, Бой насмерть, Боевой крик, Зуботычина."
L["rm.retail.warrior.fury.Name"] = "Боевой помощник Blizzard"
L["rm.retail.warrior.fury.Description"] = "Рекомендуется для специализации «Неистовство» в Midnight. Показывает предложение Боевого помощника Blizzard (Буйство, Кровожадность, Яростный выпад, Казнь, Ярость Одина и Вихрь клинков) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: Безрассудство, Аватара и Копье защитника в бою, Боевой крик между боями, Зуботычина, Безудержное восстановление по готовности в бою (здоровье на Retail скрыто, поэтому момент его применения — на ваше усмотрение)."
L["rm.retail.warrior.fury.slayer.Name"] = "Истребитель, для справки (SimulationCraft)"
L["rm.retail.warrior.fury.slayer.Description"] = "Только для справки, по умолчанию выключена: порядок Истребителя от SimulationCraft читает Исступление, Безрассудство и Внезапную смерть, которые Midnight скрывает в бою; ярость на Retail скрыта, поэтому Буйство ждёт только своей стоимости. Начало боя: Рывок; Вихрь ради его эффекта против двух и более врагов, вступивших в бой; Буйство, когда Исступление заканчивается; во время Безрассудства — Буйство, Вихрь клинков, Казнь при Внезапной смерти, Ярость Одина; Сокрушающий удар; Кровавая баня; Казнь; Ярость Одина; Яростный выпад; Буйство; Кровожадность; Вихрь. Напоминания: Безрассудство, Аватара, Безудержное восстановление, Боевой крик, Зуботычина."
L["rm.retail.warrior.fury.thane.Name"] = "Горный тан, для справки (Icy Veins)"
L["rm.retail.warrior.fury.thane.Description"] = "Только для справки, по умолчанию выключена: порядок Горного тана от SimulationCraft и Icy Veins вплетает Разряд грома и читает положительные эффекты, которые Midnight скрывает в бою. Начало боя: Рывок; Вихрь ради его эффекта против двух и более; Буйство, когда Исступления нет или оно заканчивается (ярость на Retail скрыта, поэтому Буйства при 100 ед. ярости нет); Кровавая баня во время Безрассудства; Разряд грома при двух зарядах; Сокрушающий удар; Кровавая баня; Буйство во время Безрассудства; Разряд грома во время Аватары; Яростный выпад; Разряд грома; Буйство; Кровожадность; Казнь; Ярость Одина; Удар грома; Вихрь. Те же напоминания, что и в справочной ротации Истребителя."
L["rm.retail.warrior.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.warrior.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию воина). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций воина, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.warrior.protection.Name"] = "Боевой помощник Blizzard"
L["rm.retail.warrior.protection.Description"] = "Рекомендуется для специализации «Защита» в Midnight. Показывает предложение Боевого помощника Blizzard для урона и угрозы и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Предложение никогда не применяет Блок щитом и Стойкость к боли, поэтому оба напоминания загораются всякий раз, когда их можно применить и ваша цель атакует вас; игра скрывает ярость, поэтому Стойкость к боли будет загораться чаще, чем нужно. Другие напоминания: Аватара, Деморализующий крик и Копье защитника в бою, Глухая оборона и «Ни шагу назад» по готовности в бою (здоровье на Retail скрыто, поэтому момент их применения — на ваше усмотрение), Провокация в группе, когда ваша цель атакует кого-то другого, Боевой крик между боями, Зуботычина."
L["rm.retail.warrior.protection.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.warrior.protection.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins и SimulationCraft читает Блок щитом, Разряд грома и Колоссальную мощь, которые Midnight скрывает в бою; ярость и здоровье на Retail скрыты. Начало боя: Рывок; Опустошитель; Разряд грома при двух зарядах; Разрушение при пяти наложениях Колоссальной мощи; Атака щитом; Разряд грома; Мощный удар щитом; Удар грома; Казнь; Реванш; Сокрушение. Напоминания: Блок щитом, когда его эффект не действует и вы танкуете, Стойкость к боли, Аватара, Деморализующий крик, Копье защитника, Глухая оборона и «Ни шагу назад» по готовности в бою, Боевой крик, Зуботычина."
L["rm.sod.warrior.dps.Name"] = "Урон в ближнем бою (SoD)"
L["rm.sod.warrior.dps.Description"] = "Сезон открытий, уровни 1–60, руны используются по мере того, как вы их гравируете: двуручное оружие, два оружия, гладиатор и прокачка, а также любой воин сезона открытий вне Оборонительной стойки; составлено по симулятор (6-я фаза) и Wowhead (7-я и 8-я фазы). Рывок, Победный раж, Перехват, Вихрь (до него — Удар грома) против двух и более врагов, Сокрушение при трёх наложениях «Еще мощнее», Кровопускание постоянно поддерживается, Сокрушение при Всплеске крови (по готовности, если выгравирован Точный расчёт времени), Кровожадность, Смертельный удар, Сокрушение щитом (со щитом), Превосходство; затем Быстрый удар, если он выгравирован (двуручное оружие), иначе Вихрь, Яростный выпад и рунное Сокрушение (до него — Раскол брони); Казнь при 30 ярости или при Внезапной смерти; Подрезать сухожилия у предела ярости. Напоминания: Боевой и Командирский крик, Удар героя от 50 ярости (всегда, пока вас приводит в исступление Неконтролируемая ярость), Рассекающий удар, Кровавая ярость, Буйство, Инстинкт смерти, Безрассудство, Размашистые удары, прерывания. Ярость берсерка и краткий переход в Боевую стойку ради Вкуса крови есть в списке, но выключены."
L["rm.sod.warrior.dps.icyveins.Name"] = "Урон в ближнем бою (SoD, Icy Veins)"
L["rm.sod.warrior.dps.icyveins.Description"] = "Страницы Icy Veins о «Неистовстве» и «Оружии» для сезона открытий — альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Казнь почти в начале приоритета ниже 20% или при Внезапной смерти, Сокрушение при Всплеске крови, Кровожадность или Смертельный удар, Вихрь, Превосходство, Яростный выпад, затем Быстрый удар и Подрезать сухожилия только при ярости выше 60; без Кровопускания; Удар героя только при ярости выше 80. Те же напоминания, что и в рекомендуемой встроенной ротации."
L["rm.sod.warrior.dps.wowhead.Name"] = "Смена стоек с предсказателем битв (SoD, Wowhead)"
L["rm.sod.warrior.dps.wowhead.Description"] = "Ротация 7-й и 8-й фаз по Wowhead для Души предсказателя битв или комплекта T1 из шести предметов (Rotation Master их не видит) — альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Смена стоек для поддержания положительных эффектов предчувствия, Удар героя почти всегда, затем Кровожадность, Сокрушение при Всплеске крови, Вихрь, Яростный выпад и Подрезать сухожилия; без Кровопускания и без Превосходства. Прежде чем полагаться на неё, проверьте в игре время смены стоек."
L["rm.sod.warrior.tank.Name"] = "Танк (SoD)"
L["rm.sod.warrior.tank.Description"] = "Танк для сезона открытий; выбирается в Оборонительной стойке; составлено по Wowhead (8-я фаза) и симулятор. Рывок; против двух и более врагов — Удар грома, Ударная волна, Сокрушение щитом, Реванш, Вихрь и рунное Сокрушение; затем Сокрушение щитом всякий раз, когда Решимости защитника нет или она заканчивается, Реванш, Сокрушение щитом, Ударная волна, Казнь, Вихрь при пяти наложениях Хитрости гладиатора, рунное Сокрушение (до него — Раскол брони), Деморализующий крик и Удар грома против элитных противников, Кровопускание перед Сокрушением щитом; Сокрушение щитом и Блок щитом — только с надетым щитом. Напоминания: Боевой и Командирский крик, Блок щитом, Удар героя от 50 ярости, Рассекающий удар от 55, Кровавая ярость, Буйство, Ни шагу назад, прерывания. Провокация, Глухая оборона, Инстинкт смерти, Безрассудство и Возмездие есть в списке, но выключены; переход из Стойки гладиатора ради Казни остаётся за вами."
L["rm.tbc.warrior.dps.icyveins.Name"] = "Урон в ближнем бою (Icy Veins)"
L["rm.tbc.warrior.dps.icyveins.Description"] = "Уровни 1–70, «Оружие» или «Неистовство», по Icy Veins. Те же начало боя, напоминания и шаги для прокачки, что и в версии симулятор, но со Смертельным ударом первой идёт Казнь, с Кровожадностью Казнь идёт сразу после неё, Вихрь следует без накопления ярости, а Подрезать сухожилия — только при почти полной ярости. Тайминг Сокрушения, смена стоек и Ярость берсерка остаются за вами. Альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою» (симулятор), отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.tbc.warrior.dps.simulator.Name"] = "Урон в ближнем бою (симулятор)"
L["rm.tbc.warrior.dps.simulator.Description"] = "Уровни 1–70, «Оружие» или «Неистовство». Начинает бой Рывком, затем Победный раж, Перехват, Буйство и Вихрь, когда с вами сражаются два и более врага (до его изучения — Удар грома). С Кровожадностью или Смертельным ударом: этот удар, Вихрь при лишней ярости, Казнь, Превосходство. До их изучения: Вихрь, Казнь, Превосходство, Кровопускание. Лишняя ярость уходит на Разрушение или Раскол брони, затем на Подрезать сухожилия. Напоминает о Боевом крике, Кровавой ярости, Ударе героя или Рассекающем ударе для сброса ярости, Размашистых ударах, Инстинкте смерти, Безрассудстве и прерываниях. Тайминг Сокрушения, смена стоек и Ярость берсерка остаются за вами."
L["rm.tbc.warrior.protection.icyveins.Name"] = "Танк (Icy Veins)"
L["rm.tbc.warrior.protection.icyveins.Description"] = "Уровни 10–70; выбирается, пока вы в Оборонительной стойке, по Icy Veins. Сокрушение щитом, Реванш, затем Разрушение или Раскол брони, а в начале боя — Кровопускание, пока не изучено Сокрушение щитом. Против групп: Удар грома, а против элитных противников — Деморализующий крик. О Блоке щитом напоминает всякий раз, когда цель атакует вас и у вас есть щит. Провокация и прочие вспомогательные способности остаются за вами. Альтернатива рекомендуемой встроенной ротации танка от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.tbc.warrior.protection.wowhead.Name"] = "Танк (Wowhead)"
L["rm.tbc.warrior.protection.wowhead.Description"] = "Уровни 10–70; выбирается, пока вы в Оборонительной стойке. Сокрушение щитом, Реванш, Удар грома и Деморализующий крик поддерживаются на элитных противниках и боссах, затем Разрушение или Раскол брони. Против групп: сначала Удар грома и Деморализующий крик. Напоминает о Блоке щитом (при надетом щите) против боссов и врагов более высокого уровня, Ударе героя или Рассекающем ударе, Боевом крике, Кровавой ярости, Ударе щитом, а в экстренных случаях — о «Ни шагу назад» и Глухой обороне. Провокация и прочие вспомогательные способности остаются за вами."
